package org.apache.commons.text.similarity;

import org.junit.Test;
import static org.junit.Assert.*;
import static org.evosuite.runtime.EvoAssertions.*;
import java.nio.CharBuffer;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class LevenshteinDistance_ESTest_test05 extends LevenshteinDistance_ESTest_scaffolding {

    /**
     * When the actual edit distance between the two sequences is greater than
     * the configured threshold, {@link LevenshteinDistance#apply} returns -1
     * instead of the real distance.
     */
    @Test(timeout = 4000)
    public void applyReturnsMinusOneWhenDistanceExceedsThreshold() throws Throwable {
        // "left" is an 8-character sequence: seven '�' characters and a ';' at index 3.
        char[] leftChars = new char[8];
        leftChars[3] = ';';
        CharBuffer left = CharBuffer.wrap(leftChars);

        // "right" is a 14-character string that shares almost nothing with "left".
        String right = "d0tT~H04{j;2W=";

        // A threshold of 13 caps how large a distance the algorithm will report.
        LevenshteinDistance distanceWithThreshold = new LevenshteinDistance(Integer.valueOf(13));

        Integer distance = distanceWithThreshold.apply((CharSequence) left, (CharSequence) right);

        // The true distance exceeds the threshold of 13, so -1 is returned.
        assertEquals(-1, (int) distance);
    }
}
